function minAnagramLength(s) {
  const n = s.length;
  for (let len = 1; len <= n; len++) {
    if (n % len !== 0) continue;
    const first = new Array(26).fill(0);
    for (let i = 0; i < len; i++) {
      first[s.charCodeAt(i) - 97]++;
    }
    let valid = true;
    for (let start = len; start < n && valid; start += len) {
      const count = new Array(26).fill(0);
      for (let i = start; i < start + len; i++) {
        count[s.charCodeAt(i) - 97]++;
      }
      valid = count.every((c, letter) => c === first[letter]);
    }
    if (valid) return len;
  }
  return n;
}

