function minAnagramLength(s) {
  // Split into equal pieces and compare each piece's sorted letters.
  for (let size = 1; size <= s.length; size++) {
    if (s.length % size) continue;
    const pieces = [];
    for (let i = 0; i < s.length; i += size) pieces.push(s.slice(i, i + size).split('').sort().join(''));
    if (pieces.every(p => p === pieces[0])) return size;
  }
  return s.length;
}

