function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const alphabet = size === 'large' ? int(2, 26) : (rand() < 0.1 ? 1 : int(2, 3));
  const letter = () => String.fromCharCode(97 + int(0, alphabet - 1));
  const shuffle = (arr) => {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  };
  if (size !== 'large' && rand() < 0.2) return [Array.from({ length: int(1, 10) }, letter).join('')];
  const len = size === 'large' ? int(1, 60) : int(1, 4);
  const blocks = size === 'large' ? Math.floor(10000 / len) : int(1, 4);
  const t = Array.from({ length: len }, letter);
  const chars = [];
  for (let b = 0; b < blocks; b++) chars.push(...shuffle([...t]));
  // Sometimes swap two letters far apart so that only a longer t works.
  if (rand() < 0.35 && chars.length > 1) {
    const i = int(0, len - 1);
    const j = chars.length - 1 - int(0, len - 1);
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  return [chars.join('')];
}
